        <p class="onboarding-subtitle">
          Let's set up your workspace. Tell us a bit about yourself.
        </p>

        <!-- Form -->
        <form onSubmit="{handleSubmit}" class="onboarding-form">
          <div class="form-field">
            <label for="displayName">Display Name</label>
            <input
              id="displayName"
              type="text"
              value="{displayName}"
              onInput="{(e) => setDisplayName(e.target.value)}"
              placeholder="Your name"
              required
            />
            <span class="error" if="{errors.displayName}">{errors.displayName}</span>
          </div>

          <div class="form-field">
            <label for="username">Username</label>
            <input
              id="username"
              type="text"
              value="{username}"
              onInput="{handleUsernameInput}"
              placeholder="your_username"
              required
            />
            <span class="hint">Letters, numbers, and underscores only</span>
            <span class="error" if="{errors.username}">{errors.username}</span>
          </div>

          <button
            type="submit"
            class="primary-button"
            disabled="{isSubmitting || !isValid}"
          >
            {isSubmitting ? 'Creating...' : 'Get Started'}
          </button>
        </form>
      </div>
    </div>
  </Template>

  <Script>
    const validateUsername = (value) => {
      if (!value) return 'Username is required';
      if (value.length < 3) return 'Username must be at least 3 characters';
      if (value.length > 30) return 'Username must be 30 characters or less';
      if (!/^[a-zA-Z0-9_]+$/.test(value)) return 'Only letters, numbers, and underscores allowed';
      return null;
    };

    const validateDisplayName = (value) => {
      if (!value?.trim()) return 'Display name is required';
      if (value.length > 100) return 'Display name must be 100 characters or less';
      return null;
    };

    const isValid = computed(() => {
      return displayName.value.trim() && 
             username.value && 
             !validateUsername(username.value) &&
             !validateDisplayName(displayName.value);
    });

    const handleUsernameInput = (e) => {
      const value = e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, '');
      setUsername(value);
    };

    const handleSubmit = async (e) => {
      e.preventDefault();

      const nameError = validateDisplayName(displayName.value);
      const usernameError = validateUsername(username.value);

      if (nameError || usernameError) {
        setErrors({ displayName: nameError, username: usernameError });
        return;
      }

      setIsSubmitting(true);
      setErrors({});

      try {
        await props.onCreate(displayName.value.trim(), username.value);
      } catch (error) {
        setErrors({ submit: error.message });
      } finally {
        setIsSubmitting(false);
      }
    };
