  let cursor = Cursor::new(file_data);
  let mut workbook: Xlsx<_> = open_workbook_from_rs(cursor)?;

  let sheet_name = if workbook.sheet_names().contains(&"Entries".to_string()) {
    "Entries"
  } else {
    workbook.sheet_names().first().ok_or(Error::NoSheets)?
