use tauri::{CustomMenuItem, SystemTray, SystemTrayMenu, SystemTrayEvent, Manager};

fn create_tray_menu(state: &StopwatchState) -> SystemTrayMenu {
  let status_label = if state.is_running {
    format!("Running: {}", format_duration(state.elapsed))
  } else {
    "Idle".to_string()
  };

  let mut menu = SystemTrayMenu::new()
    .add_item(CustomMenuItem::new("status", status_label).disabled())
    .add_native_item(SystemTrayMenuItem::Separator);

  if state.is_running {
    menu = menu.add_item(CustomMenuItem::new("stop", "Stop Timer"));
  } else {
    menu = menu.add_item(CustomMenuItem::new("start", "Start Timer"));
    if state.can_resume {
      menu = menu.add_item(CustomMenuItem::new("resume", "Resume Timer"));
    }
  }

  menu.add_native_item(SystemTrayMenuItem::Separator)
    .add_item(CustomMenuItem::new("show", "Show Window"))
    .add_item(CustomMenuItem::new("quit", "Quit"))
}

fn handle_tray_event(app: &AppHandle, event: SystemTrayEvent) {
  match event {
    SystemTrayEvent::MenuItemClick { id, .. } => {
      match id.as_str() {
        "start" => start_stopwatch(app),
        "stop" => stop_stopwatch(app),
        "resume" => resume_stopwatch(app),
        "show" => show_main_window(app),
        "quit" => app.exit(0),
        _ => {}
      }
    }
    _ => {}
  }
}

fn main() {
  let tray = SystemTray::new().with_menu(create_tray_menu(&StopwatchState::default()));

  tauri::Builder::default()
    .system_tray(tray)
    .on_system_tray_event(handle_tray_event)
    .run(tauri::generate_context!())
    .expect("error while running tauri application");
}
