// Rust/Tauri
struct StopwatchState {
  is_running: bool,
  start_time: Option<DateTime<Utc>>,
  elapsed_seconds: i64,
  description: String,
  project_id: Option<i64>,
}

#[tauri::command]
fn start_stopwatch(state: State<Mutex<StopwatchState>>, app: AppHandle, description: String, project_id: Option<i64>) -> Result<StopwatchState> {
  let mut sw_state = state.lock().unwrap();
  sw_state.is_running = true;
  sw_state.start_time = Some(Utc::now());
  sw_state.description = description;
  sw_state.project_id = project_id;

  persist_stopwatch_state(&sw_state)?;
  app.emit_all("stopwatch:started", &*sw_state)?;
  update_tray_menu(&app, &sw_state);

  Ok(sw_state.clone())
}

#[tauri::command]
fn stop_stopwatch(state: State<Mutex<StopwatchState>>, app: AppHandle, db: State<SqlitePool>) -> Result<TimeEntry> {
  let mut sw_state = state.lock().unwrap();
  let entry = create_time_entry(&db, &sw_state).await?;

  sw_state.is_running = false;
  sw_state.start_time = None;
  sw_state.elapsed_seconds = 0;

  persist_stopwatch_state(&sw_state)?;
  app.emit_all("stopwatch:stopped", &entry)?;
  update_tray_menu(&app, &sw_state);

  Ok(entry)
}

// Frontend (React/XMLUI)
function useStopwatch() {
  const [state, setState] = useState(null);

  useEffect(() => {
    // Listen to Tauri events
    const unlisten = listen('stopwatch:started', (event) => {
      setState(event.payload);
    });

    // Get initial state
    invoke('get_stopwatch_state').then(setState);

    return () => unlisten();
  }, []);

  const start = (description, projectId) => {
    return invoke('start_stopwatch', { description, projectId });
  };

  const stop = () => {
    return invoke('stop_stopwatch');
  };

  return { state, start, stop };
}
